// Opt-in fault actor in one fully owned fullCID. Read only the witnessed
// worker's browser subtree. Never read cmdline, environment or credentials.
import assert from 'node:assert/strict';
import {readFileSync,readlinkSync,readdirSync} from 'node:fs';
const value=JSON.parse(process.argv[2]);
function row(pid){const text=readFileSync('/proc/'+pid+'/stat','utf8'),n=text.lastIndexOf(') '),fields=text.slice(n+2).trim().split(/\s+/);return {pid,ppid:Number(fields[1]),startTicks:fields[19],namespace:readlinkSync('/proc/'+pid+'/ns/pid'),exe:readlinkSync('/proc/'+pid+'/exe'),comm:text.slice(text.indexOf('(')+1,n)};}
function childIds(pid){const threads=readdirSync('/proc/'+pid+'/task');assert.ok(threads.length<=256);const ids=new Set();for(const tid of threads){assert.match(tid,/^[0-9]+$/);let text;try{text=readFileSync('/proc/'+pid+'/task/'+tid+'/children','utf8');}catch(error){if(error.code==='ENOENT')continue;throw error;}for(const id of text.trim().split(/\s+/).filter(Boolean)){assert.match(id,/^[0-9]+$/);ids.add(Number(id));assert.ok(ids.size<=32);}}return [...ids];}
const bootId=readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim(),root=row(value.root.pid);assert.equal(bootId,value.bootId);assert.equal(root.startTicks,value.root.startTicks);assert.equal(root.namespace,value.root.pidNamespace);assert.equal(readlinkSync('/proc/self/ns/pid'),root.namespace);assert.equal(root.ppid,1);
const children=childIds(root.pid).map(row);assert.ok(children.length>=2&&children.length<=16);assert.ok(children.every(x=>x.ppid===root.pid&&x.namespace===root.namespace));const browsers=children.filter(x=>x.exe==='/browser/headless_shell'),brokers=children.filter(x=>x.exe==='/project/native/bin/aarch64-unknown-linux-gnu/remote-paint-broker');assert.equal(browsers.length,1);assert.equal(brokers.length,1);const browser=browsers[0],broker=brokers[0],descendants=[],seen=new Set([browser.pid]),queue=[browser];
while(queue.length){const parent=queue.shift();for(const pid of childIds(parent.pid)){assert.equal(seen.has(pid),false);seen.add(pid);assert.ok(seen.size<=32);let child;try{child=row(pid);}catch(error){if(error.code==='ENOENT'||error.code==='ESRCH')continue;throw error;}assert.equal(child.ppid,parent.pid);assert.equal(child.namespace,root.namespace);assert.equal(child.exe,'/browser/headless_shell');descendants.push(child);queue.push(child);}}
const threadNames={};for(const child of [browser,...descendants]){const names=new Set(),threads=readdirSync('/proc/'+child.pid+'/task');assert.ok(threads.length<=256);for(const tid of threads){assert.match(tid,/^[0-9]+$/);let name;try{name=readFileSync('/proc/'+child.pid+'/task/'+tid+'/comm','utf8').trim();}catch(error){if(error.code==='ENOENT')continue;throw error;}assert.ok(name.length<=16);names.add(name);assert.ok(names.size<=64);}threadNames[child.pid]=[...names].sort();}
// This pinned build exposes headless_shell as every process's main comm.
// Its sole about:blank renderer owns the separate Blink Compositor thread;
// the GPU process instead owns VizCompositorTh. Require the child IO thread
// and exact browser -> zygote -> renderer relationship as additional checks.
const rendererCandidates=descendants.filter(child=>threadNames[child.pid].includes('Compositor')&&threadNames[child.pid].includes('Chrome_ChildIOT')&&!threadNames[child.pid].includes('VizCompositorTh')&&descendants.some(parent=>parent.pid===child.ppid&&parent.ppid===browser.pid&&threadNames[parent.pid].length===1&&threadNames[parent.pid][0]==='headless_shell'));
if(value.action==='snapshot'){console.log(JSON.stringify({scope:'bounded kernel identity of witnessed worker browser subtree; no argv/environment',bootId,root,children,descendants,threadNames,rendererCandidates}));}
else{
 assert.equal(value.action,'terminate-renderer');assert.equal(rendererCandidates.length,1);const target=rendererCandidates[0];assert.equal(target.pid,value.target.pid);for(const key of ['pid','ppid','startTicks','namespace','exe','comm'])assert.equal(target[key],value.target[key]);assert.equal(target.exe,'/browser/headless_shell');for(const [current,expected]of [[browser,value.browser],[broker,value.broker]])for(const key of ['pid','ppid','startTicks','namespace','exe'])assert.equal(current[key],expected[key]);
 // Re-read each ancestor and target after discovery, before signal.
 let ancestor=target;while(ancestor.pid!==browser.pid){const current=row(ancestor.pid);assert.deepEqual(current,ancestor);ancestor=ancestor.ppid===browser.pid?browser:descendants.find(x=>x.pid===ancestor.ppid);assert.ok(ancestor);}assert.deepEqual(row(browser.pid),browser);assert.deepEqual(row(broker.pid),broker);assert.deepEqual(row(root.pid),root);process.kill(target.pid,'SIGKILL');console.log(JSON.stringify({scope:'exact owned renderer kernel identity revalidated before signal',bootId,root,browser,broker,target,rendererThreadNames:threadNames[target.pid],signal:'SIGKILL',signalDelivered:true,argvEnvironmentRead:false}));
}
